import clsx from 'clsx';
import type { PropsWithChildren, ReactNode } from 'react';
import React, { useMemo } from 'react';
import { useIntl } from 'react-intl';
import { isElement } from 'react-is';

import { ChevronDownSmallIcon } from '@dynatrace/strato-icons';

import { _isTimeframeSelectorDisplayValueElement } from './DisplayValue.js';
import { _useInternalTimeframeSelectorContext } from './hooks/useInternalTimeframeSelectorContext.js';
import { useTimeframeSelectorContext } from './hooks/useTimeframeSelectorContext.js';
import {
  timeframeSelectorSuffixCSS,
  timeframeSelectorSuffixOpenCSS,
  timeframeSelectorTriggerCSS,
} from './TimeframeSelector.sty.js';
import { Button } from '../../buttons/button/Button.js';
import type { AriaLabelingProps } from '../../core/types/a11y-props.js';
import type { DataTestId } from '../../core/types/data-props.js';
import type { StylingProps } from '../../core/types/styling-props.js';
import { mergeProps as _mergeProps } from '../../core/utils/merge-props.js';

export type TimeframeSelectorTriggerProps = PropsWithChildren &
  StylingProps &
  DataTestId &
  AriaLabelingProps & {
    /**
     * The placeholder text displayed in the TimeframeSelector.Trigger.
     */
    placeholder?: ReactNode;
  };

/**
 * Typeguard function that will check if a React.Node is a TimeframeSelector.Trigger
 * @internal
 */
export function _isTimeframeSelectorTriggerElement(
  child: React.ReactNode,
): child is React.ReactElement<TimeframeSelectorTriggerProps> {
  return isElement(child) && child.type === Trigger;
}

function getDisplayValueSlot(children: ReactNode) {
  let displayValue: ReactNode[] | null = null;

  React.Children.forEach(children, (child) => {
    if (_isTimeframeSelectorDisplayValueElement(child)) {
      displayValue = displayValue || [];
      displayValue.push(child);
    }
  });

  return displayValue;
}

/**
 * A trigger component to customize a timeframe selector's trigger with custom styling, placeholder, aria labels, and data-testid.
 * If it doesn't have children, the default trigger is used. OTherwise, the `TimeframeSelector.DisplayValue` component can be used within it to define a custom display value within.
 */
export const Trigger = (props: TimeframeSelectorTriggerProps) => {
  const {
    children,
    placeholder,
    'aria-label': ariaLabel,
    className: consumerClassName,
    style: consumerStyle,
    'data-testid': dataTestId,
    ...remainingProps
  } = props;

  const intl = useIntl();

  const displayValueSlot = useMemo(
    () => getDisplayValueSlot(children),
    [children],
  );

  const {
    triggerProps,
    displayValue: contextDisplayValue,
    details,
  } = useTimeframeSelectorContext();
  const { readOnly, hasError } = _useInternalTimeframeSelectorContext();

  const displayValue = displayValueSlot ?? contextDisplayValue;
  const ariaLabelDefault = intl.formatMessage({
    defaultMessage: 'Toggle timeframe selector overlay',
    id: 'JyRZFvehPfXJpvOp',
    description: 'Aria label for the timeframe selector overlay toggle button.',
  });
  const placeholderIfEmpty = placeholder ?? contextDisplayValue;

  return (
    <Button
      {..._mergeProps(triggerProps, remainingProps)}
      data-testid={dataTestId}
      variant="emphasized"
      color={hasError ? 'critical' : 'neutral'}
      aria-label={ariaLabel ?? ariaLabelDefault}
      style={consumerStyle}
      className={clsx(
        consumerClassName,
        readOnly && timeframeSelectorTriggerCSS,
      )}
    >
      <Button.Suffix>
        <ChevronDownSmallIcon
          className={clsx(
            timeframeSelectorSuffixCSS,
            triggerProps?.['aria-expanded'] && timeframeSelectorSuffixOpenCSS,
          )}
        />
      </Button.Suffix>
      {details ? displayValue : placeholderIfEmpty}
    </Button>
  );
};

Trigger.displayName = 'TimeframeSelector.Trigger';
